// The simulations of the physics library through its C interface: fall, bounce, friction, stacks, forces, kinematic bodies, sensors and
// contacts, layers, interpolation, and that the same input gives the same bits on every run and with any number of threads.
// "sim_test --threads N --hash" runs only the pile and prints a hash of where everything ended up (for the comparison of threads).

#include "blitzphysics.h"

#include <algorithm>
#include <cmath>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <vector>

static int failures = 0;

#define CHECK(condition)                                                              \
	do {                                                                              \
		if (!(condition)) {                                                           \
			std::printf("FAILED %s:%d: %s\n", __FILE__, __LINE__, #condition);        \
			failures++;                                                               \
		}                                                                             \
	} while (0)

static bool near(float a, float b, float epsilon) { return std::fabs(a - b) <= epsilon; }

static const float dt = 1.0f / 60.0f;

static bp_body_desc desc(uint32_t shape, uint32_t motion, float a, float b, float c, float x, float y, float z)
{
	bp_body_desc d;
	bp_body_desc_default(&d);
	d.shape = shape;
	d.motion = motion;
	d.a = a;
	d.b = b;
	d.c = c;
	d.position[0] = x;
	d.position[1] = y;
	d.position[2] = z;
	d.linear_damping = 0.0f;
	d.angular_damping = 0.0f;
	return d;
}

static void pos(bp_sim* sim, bp_body body, float p[3])
{
	float q[4];
	bp_sim_body_get_transform(sim, body, p, q);
}

static void steps(bp_sim* sim, int n)
{
	for (int i = 0; i < n; i++) {
		bp_sim_step(sim, dt);
	}
}

static bp_body make_floor(bp_sim* sim, float friction = 0.5f, float restitution = 0.0f)
{
	bp_body_desc d = desc(BP_SHAPE_BOX, BP_STATIC, 50, 0.5f, 50, 0, -0.5f, 0); // The top is at y = 0.
	d.friction = friction;
	d.restitution = restitution;
	return bp_sim_body_create(sim, &d);
}

static void test_settings()
{
	bp_sim_settings s;
	CHECK(bp_sim_settings_preset(0, &s) == 1 && s.velocity_steps == 10 && s.position_steps == 2 && s.substeps == 1 && s.continuous_default == 0);
	CHECK(bp_sim_settings_preset(1, &s) == 1 && s.velocity_steps == 4 && s.position_steps == 1 && near(s.sleep_velocity, 0.06f, 1e-6f));
	CHECK(bp_sim_settings_preset(2, &s) == 1 && s.velocity_steps == 16 && s.position_steps == 4 && s.substeps == 2 && s.continuous_default == 1);
	bp_sim_settings before = s;
	CHECK(bp_sim_settings_preset(3, &s) == 0 && std::memcmp(&s, &before, sizeof(s)) == 0);

	bp_sim* sim = bp_sim_create(100, 0);
	CHECK(sim != nullptr);
	bp_sim_settings got;
	bp_sim_get_settings(sim, &got);
	CHECK(got.velocity_steps == 10 && got.deterministic == 1);
	s.velocity_steps = 0; // Not valid: at least one.
	s.substeps = 0;
	bp_sim_set_settings(sim, &s);
	bp_sim_get_settings(sim, &got);
	CHECK(got.velocity_steps == 1 && got.substeps == 1);
	float g[3] = { 0, -3, 0 }, gg[3];
	bp_sim_set_gravity(sim, g);
	bp_sim_get_gravity(sim, gg);
	CHECK(gg[1] == -3.0f);
	bp_sim_destroy(sim);
}

static void test_invalid()
{
	bp_sim* sim = bp_sim_create(2, 0);
	bp_body_desc d = desc(BP_SHAPE_BOX, BP_DYNAMIC, 1, 1, 1, 0, 0, 0);
	d.mass = 0;
	CHECK(bp_sim_body_create(sim, &d) == 0); // No mass.
	d.mass = 1;
	d.a = 0;
	CHECK(bp_sim_body_create(sim, &d) == 0); // No size.
	d.a = 1;
	d.shape = BP_SHAPE_MESH;
	CHECK(bp_sim_body_create(sim, &d) == 0); // No mesh.
	d.shape = BP_SHAPE_CONVEX_HULL;
	CHECK(bp_sim_body_create(sim, &d) == 0); // No points.
	d.shape = BP_SHAPE_BOX;
	d.layer = 64;
	CHECK(bp_sim_body_create(sim, &d) == 0);
	d.layer = 0;
	d.lock_linear = 7;
	d.lock_angular = 7;
	CHECK(bp_sim_body_create(sim, &d) == 0); // Nothing can move.
	d.lock_linear = d.lock_angular = 0;
	bp_body a = bp_sim_body_create(sim, &d), b = bp_sim_body_create(sim, &d);
	CHECK(a && b && a != b);
	CHECK(bp_sim_body_create(sim, &d) == 0); // Full (2 bodies).
	CHECK(bp_sim_body_count(sim) == 2);
	bp_sim_body_destroy(sim, a);
	CHECK(bp_sim_body_count(sim) == 1);
	CHECK(bp_sim_body_create(sim, &d) != 0); // Room again.
	bp_sim_destroy(sim);
}

static void test_fall()
{
	bp_sim* sim = bp_sim_create(0, 0);
	bp_body_desc d = desc(BP_SHAPE_BOX, BP_DYNAMIC, 0.5f, 0.5f, 0.5f, 0, 100, 0);
	bp_body body = bp_sim_body_create(sim, &d);
	steps(sim, 60);
	float p[3];
	pos(sim, body, p);
	// Semi-implicit Euler: y = y0 - g dt^2 n (n + 1) / 2 for n steps.
	float expected = 100.0f - 9.81f * dt * dt * 60 * 61 / 2;
	CHECK(near(p[1], expected, 0.05f));
	float lin[3], ang[3];
	bp_sim_body_get_velocity(sim, body, lin, ang);
	CHECK(near(lin[1], -9.81f, 0.05f));
	bp_sim_destroy(sim);
}

static void test_rest_and_sleep()
{
	bp_sim* sim = bp_sim_create(0, 0);
	make_floor(sim);
	bp_body_desc d = desc(BP_SHAPE_SPHERE, BP_DYNAMIC, 0.5f, 0, 0, 0, 3, 0);
	bp_body ball = bp_sim_body_create(sim, &d);
	CHECK(bp_sim_body_is_awake(sim, ball) == 1);
	steps(sim, 300);
	float p[3];
	pos(sim, ball, p);
	CHECK(near(p[1], 0.5f, 0.05f));
	CHECK(bp_sim_body_is_awake(sim, ball) == 0); // Rested for long enough.
	bp_sim_body_wake(sim, ball);
	CHECK(bp_sim_body_is_awake(sim, ball) == 1);
	bp_sim_destroy(sim);
}

static float bounce_height(float restitution)
{
	bp_sim* sim = bp_sim_create(0, 0);
	make_floor(sim, 0.5f, restitution);
	bp_body_desc d = desc(BP_SHAPE_SPHERE, BP_DYNAMIC, 0.5f, 0, 0, 0, 5.5f, 0);
	d.restitution = restitution;
	bp_body ball = bp_sim_body_create(sim, &d);
	float highest_after = 0;
	bool  hit = false;
	for (int i = 0; i < 240; i++) {
		bp_sim_step(sim, dt);
		float p[3], lin[3], ang[3];
		pos(sim, ball, p);
		bp_sim_body_get_velocity(sim, ball, lin, ang);
		if (!hit && lin[1] > 0) {
			hit = true;
		}
		if (hit) {
			highest_after = std::max(highest_after, p[1]);
		}
	}
	bp_sim_destroy(sim);
	return highest_after;
}

static void test_restitution()
{
	float none = bounce_height(0.0f), full = bounce_height(1.0f), half = bounce_height(0.5f);
	CHECK(none < 1.0f);                    // Does not come back up.
	CHECK(full > 4.2f && full < 5.8f);     // Comes back (nearly) to where it fell from (5.5 high center, 0.5 radius).
	CHECK(half > 0.5f + 5.0f * 0.25f * 0.7f && half < 0.5f + 5.0f * 0.25f * 1.3f); // A quarter of the fall height at 0.5.
}

static float slide(float friction)
{
	bp_sim* sim = bp_sim_create(0, 0);
	float angle = 20.0f * 3.14159265f / 180.0f;
	float q[4] = { 0, 0, std::sin(angle / 2), std::cos(angle / 2) };
	bp_body_desc ramp = desc(BP_SHAPE_BOX, BP_STATIC, 20, 0.5f, 20, 0, 0, 0);
	ramp.friction = friction;
	ramp.rotation[2] = q[2];
	ramp.rotation[3] = q[3];
	bp_sim_body_create(sim, &ramp);
	// The surface normal is (-sin, cos, 0); the box is put on it.
	float n[3] = { -std::sin(angle), std::cos(angle), 0 };
	bp_body_desc box = desc(BP_SHAPE_BOX, BP_DYNAMIC, 0.5f, 0.5f, 0.5f, n[0] * 1.01f, n[1] * 1.01f, 0);
	box.friction = friction;
	box.rotation[2] = q[2];
	box.rotation[3] = q[3];
	bp_body body = bp_sim_body_create(sim, &box);
	float start[3], end[3];
	pos(sim, body, start);
	steps(sim, 60);
	pos(sim, body, end);
	bp_sim_destroy(sim);
	return std::sqrt((end[0] - start[0]) * (end[0] - start[0]) + (end[1] - start[1]) * (end[1] - start[1]));
}

static void test_friction()
{
	CHECK(slide(0.9f) < 0.1f); // tan(20 degrees) is 0.36: it stays.
	CHECK(slide(0.0f) > 1.0f); // Slides about 1.7 meters in a second.
}

static void test_stack()
{
	bp_sim* sim = bp_sim_create(0, 0);
	make_floor(sim);
	std::vector<bp_body> boxes;
	for (int i = 0; i < 10; i++) {
		bp_body_desc d = desc(BP_SHAPE_BOX, BP_DYNAMIC, 0.5f, 0.5f, 0.5f, 0, 0.5f + i * 1.0f + 0.001f * i, 0);
		boxes.push_back(bp_sim_body_create(sim, &d));
	}
	steps(sim, 600);
	for (int i = 0; i < 10; i++) {
		float p[3];
		pos(sim, boxes[i], p);
		CHECK(near(p[1], 0.5f + i, 0.15f));
		CHECK(near(p[0], 0.0f, 0.1f) && near(p[2], 0.0f, 0.1f));
	}
	bp_sim_destroy(sim);
}

static void test_forces()
{
	bp_sim* sim = bp_sim_create(0, 0);
	float zero[3] = { 0, 0, 0 };
	bp_sim_set_gravity(sim, zero);
	bp_body_desc d = desc(BP_SHAPE_BOX, BP_DYNAMIC, 0.5f, 0.5f, 0.5f, 0, 0, 0);
	d.mass = 2.0f;
	bp_body body = bp_sim_body_create(sim, &d);
	float lin[3], ang[3];

	float impulse[3] = { 10, 0, 0 };
	bp_sim_body_add_impulse(sim, body, impulse, nullptr);
	bp_sim_body_get_velocity(sim, body, lin, ang);
	CHECK(near(lin[0], 5.0f, 1e-3f)); // 10 N s on 2 kg.

	float stop[3] = { 0, 0, 0 };
	bp_sim_body_set_velocity(sim, body, stop, stop);
	float force[3] = { 4, 0, 0 };
	for (int i = 0; i < 60; i++) { // A force lasts for one step.
		bp_sim_body_add_force(sim, body, force, nullptr);
		bp_sim_step(sim, dt);
	}
	bp_sim_body_get_velocity(sim, body, lin, ang);
	CHECK(near(lin[0], 2.0f, 0.02f)); // 4 N / 2 kg for 1 s.

	bp_sim_body_set_velocity(sim, body, stop, stop);
	float torque[3] = { 0, 1, 0 };
	for (int i = 0; i < 30; i++) {
		bp_sim_body_add_torque(sim, body, torque);
		bp_sim_step(sim, dt);
	}
	bp_sim_body_get_velocity(sim, body, lin, ang);
	CHECK(ang[1] > 0.1f && near(ang[0], 0.0f, 1e-3f));

	// Mass changes what a force does.
	bp_sim_body_set_velocity(sim, body, stop, stop);
	bp_sim_body_set_mass(sim, body, 4.0f);
	bp_sim_body_add_impulse(sim, body, impulse, nullptr);
	bp_sim_body_get_velocity(sim, body, lin, ang);
	CHECK(near(lin[0], 2.5f, 1e-3f));

	// Locked axes: only x may move.
	bp_body_desc l = desc(BP_SHAPE_BOX, BP_DYNAMIC, 0.5f, 0.5f, 0.5f, 5, 5, 5);
	l.lock_linear = 2 | 4;
	l.lock_angular = 7;
	bp_body locked = bp_sim_body_create(sim, &l);
	float diagonal[3] = { 3, 3, 3 };
	bp_sim_body_set_velocity(sim, locked, diagonal, stop);
	steps(sim, 30);
	float p[3];
	pos(sim, locked, p);
	CHECK(p[0] > 6.0f && near(p[1], 5.0f, 1e-3f) && near(p[2], 5.0f, 1e-3f));
	bp_sim_destroy(sim);
}

static void test_kinematic()
{
	bp_sim* sim = bp_sim_create(0, 0);
	float zero[3] = { 0, 0, 0 };
	bp_sim_set_gravity(sim, zero);
	bp_body_desc w = desc(BP_SHAPE_BOX, BP_KINEMATIC, 0.5f, 2, 5, 0, 0, 0);
	bp_body wall = bp_sim_body_create(sim, &w);
	bp_body_desc d = desc(BP_SHAPE_BOX, BP_DYNAMIC, 0.5f, 0.5f, 0.5f, 3, 0, 0);
	bp_body crate = bp_sim_body_create(sim, &d);
	float q[4] = { 0, 0, 0, 1 };
	for (int i = 1; i <= 120; i++) {
		float to[3] = { i * 0.05f, 0, 0 }; // 3 meters per second.
		bp_sim_body_set_transform(sim, wall, to, q, 0);
		bp_sim_step(sim, dt);
	}
	float p[3], c[3];
	pos(sim, wall, p);
	pos(sim, crate, c);
	CHECK(near(p[0], 6.0f, 1e-3f));  // It went where it was told, whatever was in the way.
	CHECK(c[0] > p[0] + 0.5f);       // The crate was pushed along in front of it.

	// Teleporting does not push by speed.
	float far[3] = { 100, 0, 0 };
	bp_sim_body_set_transform(sim, wall, far, q, 1);
	pos(sim, wall, p);
	CHECK(near(p[0], 100.0f, 1e-3f));
	bp_sim_destroy(sim);
}

static void test_contacts_and_sensors()
{
	bp_sim* sim = bp_sim_create(0, 0);
	bp_body_desc f = desc(BP_SHAPE_BOX, BP_STATIC, 50, 0.5f, 50, 0, -0.5f, 0);
	f.report_contacts = 1;
	bp_body floor = bp_sim_body_create(sim, &f);
	bp_body_desc d = desc(BP_SHAPE_SPHERE, BP_DYNAMIC, 0.5f, 0, 0, 0, 0.6f, 0);
	d.user = 77;
	bp_body ball = bp_sim_body_create(sim, &d);
	CHECK(bp_sim_contact_count(sim) == 0);
	steps(sim, 20);
	CHECK(bp_sim_contact_count(sim) == 1);
	bp_contact c;
	bp_sim_contact_get(sim, 0, &c);
	CHECK(c.body_a == floor && c.body_b == ball && c.user_b == 77 && c.sensor == 0);
	CHECK(near(c.normal[1], 1.0f, 0.05f)); // From the floor to the ball.
	CHECK(c.depth < 0.05f);
	bp_sim_contacts_clear(sim);
	CHECK(bp_sim_contact_count(sim) == 0);
	bp_sim_destroy(sim);

	// A sensor sees things pass through it, and does not stop them.
	sim = bp_sim_create(0, 0);
	bp_body_desc s = desc(BP_SHAPE_BOX, BP_STATIC, 5, 1, 5, 0, 5, 0);
	s.sensor = 1;
	s.report_contacts = 1;
	bp_body zone = bp_sim_body_create(sim, &s);
	bp_body_desc b = desc(BP_SHAPE_SPHERE, BP_DYNAMIC, 0.5f, 0, 0, 0, 10, 0);
	bp_body falling = bp_sim_body_create(sim, &b);
	bool seen = false;
	for (int i = 0; i < 120; i++) {
		bp_sim_step(sim, dt);
	}
	for (uint32_t i = 0; i < bp_sim_contact_count(sim); i++) {
		bp_sim_contact_get(sim, i, &c);
		seen = seen || ((c.sensor == 1) && ((c.body_a == zone && c.body_b == falling) || (c.body_a == falling && c.body_b == zone)));
	}
	float p[3];
	pos(sim, falling, p);
	CHECK(seen);
	CHECK(p[1] < 0.0f); // It fell through.
	bp_sim_destroy(sim);
}

static void test_layers()
{
	bp_sim* sim = bp_sim_create(0, 0);
	bp_body_desc f = desc(BP_SHAPE_BOX, BP_STATIC, 50, 0.5f, 50, 0, -0.5f, 0);
	f.layer = 2;
	bp_sim_body_create(sim, &f);
	bp_body_desc a = desc(BP_SHAPE_SPHERE, BP_DYNAMIC, 0.5f, 0, 0, 0, 2, 0);
	a.layer = 1;
	a.mask = ~(uint64_t(1) << 2); // Does not collide with layer 2.
	bp_body passes = bp_sim_body_create(sim, &a);
	bp_body_desc b = desc(BP_SHAPE_SPHERE, BP_DYNAMIC, 0.5f, 0, 0, 5, 2, 0);
	b.layer = 3;
	bp_body lands = bp_sim_body_create(sim, &b);
	steps(sim, 120);
	float p[3];
	pos(sim, passes, p);
	CHECK(p[1] < -3.0f);
	pos(sim, lands, p);
	CHECK(near(p[1], 0.5f, 0.05f));
	// Both have to want it.
	bp_sim_body_set_layer(sim, lands, 3, ~(uint64_t(1) << 2));
	float up[3] = { 0, 5, 0 }, zero[3] = { 0, 0, 0 };
	float to[3] = { 5, 3, 0 }, q[4] = { 0, 0, 0, 1 };
	bp_sim_body_set_transform(sim, lands, to, q, 1);
	bp_sim_body_set_velocity(sim, lands, zero, zero);
	(void)up;
	steps(sim, 120);
	pos(sim, lands, p);
	CHECK(p[1] < -1.0f);
	bp_sim_destroy(sim);
}

static void test_motion_change()
{
	bp_sim* sim = bp_sim_create(0, 0);
	bp_body_desc d = desc(BP_SHAPE_BOX, BP_STATIC, 0.5f, 0.5f, 0.5f, 0, 10, 0);
	bp_body body = bp_sim_body_create(sim, &d);
	steps(sim, 30);
	float p[3];
	pos(sim, body, p);
	CHECK(near(p[1], 10.0f, 1e-4f)); // Static: stays.
	bp_sim_body_set_motion(sim, body, BP_DYNAMIC);
	steps(sim, 30);
	pos(sim, body, p);
	CHECK(p[1] < 9.0f); // Falls now.
	bp_sim_body_set_motion(sim, body, BP_STATIC);
	float at = p[1];
	steps(sim, 30);
	pos(sim, body, p);
	CHECK(near(p[1], at, 1e-4f));
	// A mesh can be static or kinematic, not dynamic.
	const float    positions[] = { -1, 0, -1, 1, 0, -1, 1, 0, 1, -1, 0, 1 };
	const uint32_t indices[]   = { 0, 2, 1, 0, 3, 2 };
	bp_mesh*       mesh        = bp_mesh_create(positions, 4, indices, 2);
	bp_body_desc   m           = desc(BP_SHAPE_MESH, BP_STATIC, 0, 0, 0, 0, 0, 0);
	m.mesh = mesh;
	bp_body floor = bp_sim_body_create(sim, &m);
	CHECK(floor != 0);
	bp_sim_body_set_motion(sim, floor, BP_DYNAMIC);
	bp_body_desc ball = desc(BP_SHAPE_SPHERE, BP_DYNAMIC, 0.25f, 0, 0, 0, 1, 0);
	bp_body b = bp_sim_body_create(sim, &ball);
	steps(sim, 120);
	pos(sim, floor, p);
	CHECK(near(p[1], 0.0f, 1e-4f)); // Refused: it did not fall.
	pos(sim, b, p);
	CHECK(near(p[1], 0.25f, 0.05f));
	m.motion = BP_DYNAMIC;
	CHECK(bp_sim_body_create(sim, &m) == 0);
	bp_mesh_destroy(mesh); // The body keeps it.
	steps(sim, 10);
	bp_sim_destroy(sim);
}

static void test_shapes()
{
	bp_sim* sim = bp_sim_create(0, 0);
	make_floor(sim);
	const float hull[] = { -0.5f, -0.5f, -0.5f, 0.5f, -0.5f, -0.5f, 0.5f, -0.5f, 0.5f, -0.5f, -0.5f, 0.5f, 0, 0.5f, 0 }; // A pyramid.
	struct { uint32_t shape; float a, b, c; float rest; } cases[] = {
		{ BP_SHAPE_BOX, 0.5f, 0.3f, 0.4f, 0.3f }, { BP_SHAPE_SPHERE, 0.4f, 0, 0, 0.4f }, { BP_SHAPE_ELLIPSOID, 0.5f, 0.25f, 0.4f, 0.25f },
		{ BP_SHAPE_CAPSULE, 0.3f, 0.5f, 0, 0.8f }, { BP_SHAPE_CYLINDER, 0.4f, 0.5f, 0, 0.5f }, { BP_SHAPE_TAPERED_CAPSULE, 0.3f, 0.5f, 0.5f, -1 },
		{ BP_SHAPE_CONVEX_HULL, 0, 0, 0, 0.5f },
	};
	std::vector<bp_body> bodies;
	for (int i = 0; i < 7; i++) {
		bp_body_desc d = desc(cases[i].shape, BP_DYNAMIC, cases[i].a, cases[i].b, cases[i].c, i * 3.0f - 9.0f, 2, 0);
		if (cases[i].shape == BP_SHAPE_CONVEX_HULL) {
			d.points = hull;
			d.point_count = 5;
		}
		bodies.push_back(bp_sim_body_create(sim, &d));
		CHECK(bodies.back() != 0);
	}
	steps(sim, 240);
	for (int i = 0; i < 7; i++) {
		float p[3];
		pos(sim, bodies[i], p);
		CHECK(p[1] > -0.1f && p[1] < 1.5f); // On the floor, none fell through or flew off.
		if (cases[i].rest > 0 && cases[i].shape != BP_SHAPE_CAPSULE && cases[i].shape != BP_SHAPE_CONVEX_HULL) {
			CHECK(near(p[1], cases[i].rest, 0.12f) || cases[i].shape == BP_SHAPE_BOX);
		}
	}
	// Mass of an ellipsoid follows its volume: the same force gives the speed of the mass that was asked for.
	bp_sim_destroy(sim);
}

static void test_interpolation()
{
	bp_sim* sim = bp_sim_create(0, 0);
	float zero[3] = { 0, 0, 0 };
	bp_sim_set_gravity(sim, zero);
	bp_body_desc d = desc(BP_SHAPE_BOX, BP_DYNAMIC, 0.5f, 0.5f, 0.5f, 0, 0, 0);
	bp_body body = bp_sim_body_create(sim, &d);
	float v[3] = { 6, 0, 0 };
	bp_sim_body_set_velocity(sim, body, v, zero);
	bp_sim_step(sim, dt); // 0.1 meters.
	float p[3], q[4], now[3], was[3], half[3];
	bp_sim_body_get_transform_interpolated(sim, body, 1.0f, now, q);
	bp_sim_body_get_transform_interpolated(sim, body, 0.0f, was, q);
	bp_sim_body_get_transform_interpolated(sim, body, 0.5f, half, q);
	pos(sim, body, p);
	CHECK(near(now[0], p[0], 1e-6f) && near(was[0], 0.0f, 1e-5f) && near(half[0], p[0] * 0.5f, 1e-4f));
	// Putting a body somewhere does not smear it from where it was.
	float to[3] = { 50, 0, 0 };
	bp_sim_body_set_transform(sim, body, to, q, 0);
	bp_sim_body_get_transform_interpolated(sim, body, 0.0f, was, q);
	CHECK(near(was[0], 50.0f, 1e-4f));
	bp_sim_destroy(sim);
}

// A pile of all kinds of bodies, the same way every time.
static uint64_t pile(uint32_t threads, int step_count)
{
	bp_sim* sim = bp_sim_create(0, threads);
	make_floor(sim, 0.6f, 0.1f);
	bp_body_desc wall = desc(BP_SHAPE_BOX, BP_STATIC, 0.5f, 3, 10, 12, 3, 0);
	wall.restitution = 0.3f;
	bp_sim_body_create(sim, &wall);
	const float hull[] = { -0.5f, -0.5f, -0.5f, 0.5f, -0.5f, -0.5f, 0.5f, -0.5f, 0.5f, -0.5f, -0.5f, 0.5f, 0, 0.6f, 0 };
	uint32_t seed = 12345;
	auto next = [&seed]() { seed = seed * 1664525u + 1013904223u; return float((seed >> 8) & 0xFFFF) / 65535.0f; };
	std::vector<bp_body> bodies;
	for (int i = 0; i < 60; i++) {
		uint32_t shape[] = { BP_SHAPE_BOX, BP_SHAPE_SPHERE, BP_SHAPE_ELLIPSOID, BP_SHAPE_CAPSULE, BP_SHAPE_CYLINDER, BP_SHAPE_CONVEX_HULL };
		bp_body_desc d = desc(shape[i % 6], BP_DYNAMIC, 0.3f + next() * 0.3f, 0.3f + next() * 0.3f, 0.3f + next() * 0.3f, next() * 6 - 3, 1 + i * 0.7f, next() * 6 - 3);
		d.mass = 0.5f + next() * 4;
		d.friction = next();
		d.restitution = next() * 0.5f;
		d.report_contacts = 1;
		d.linear_damping = 0.01f;
		d.angular_damping = 0.01f;
		d.user = i;
		if (shape[i % 6] == BP_SHAPE_CONVEX_HULL) {
			d.points = hull;
			d.point_count = 5;
		}
		float axis = next() * 6.28f;
		d.rotation[0] = std::sin(axis / 2) * 0.6f;
		d.rotation[1] = std::sin(axis / 2) * 0.8f;
		d.rotation[3] = std::cos(axis / 2);
		bp_body body = bp_sim_body_create(sim, &d);
		bodies.push_back(body);
		float push[3] = { next() * 4 - 1, 0, next() * 2 - 1 }, zero[3] = { 0, 0, 0 };
		bp_sim_body_set_velocity(sim, body, push, zero);
	}
	uint64_t hash = 1469598103934665603ull;
	auto mix = [&hash](float f) {
		uint32_t bits;
		std::memcpy(&bits, &f, 4);
		hash = (hash ^ bits) * 1099511628211ull;
	};
	for (int i = 0; i < step_count; i++) {
		bp_sim_step(sim, dt);
		if (i % 50 == 0) {
			// The contacts are part of what has to be the same.
			uint32_t count = bp_sim_contact_count(sim);
			mix(float(count));
			for (uint32_t k = 0; k < count; k++) {
				bp_contact c;
				bp_sim_contact_get(sim, k, &c);
				mix(float(c.body_a));
				mix(float(c.body_b));
				mix(c.depth);
				mix(c.point[1]);
			}
			bp_sim_contacts_clear(sim);
		}
	}
	for (bp_body body : bodies) {
		float p[3], q[4];
		bp_sim_body_get_transform(sim, body, p, q);
		for (float f : p) mix(f);
		for (float f : q) mix(f);
	}
	bp_sim_destroy(sim);
	return hash;
}

static void test_determinism()
{
	uint64_t a = pile(0, 400), b = pile(0, 400);
	CHECK(a == b);
	CHECK(pile(0, 399) != a); // The hash does depend on the result.
}

int main(int argc, char** argv)
{
	uint32_t threads = 0;
	bool     hash    = false;
	for (int i = 1; i < argc; i++) {
		if (!std::strcmp(argv[i], "--threads") && i + 1 < argc) {
			threads = uint32_t(std::atoi(argv[++i]));
		} else if (!std::strcmp(argv[i], "--hash")) {
			hash = true;
		}
	}
	if (hash) {
		// The threads are those of the first simulation made.
		std::printf("%016llx\n", (unsigned long long)pile(threads, 400));
		return 0;
	}
	CHECK(bp_version() == BP_VERSION);
	test_settings();
	test_invalid();
	test_fall();
	test_rest_and_sleep();
	test_restitution();
	test_friction();
	test_stack();
	test_forces();
	test_kinematic();
	test_contacts_and_sensors();
	test_layers();
	test_motion_change();
	test_shapes();
	test_interpolation();
	test_determinism();
	if (failures) {
		std::printf("%d checks failed\n", failures);
		return 1;
	}
	std::printf("physics simulation: all checks passed\n");
	return 0;
}
